def rle_encode(s):
    out, i = [], 0
    while i < len(s):
        if s[i] == '\\':
            out.append('\\\\')
            i += 1
            continue
        j = i
        while j < len(s) and s[j] == s[i] and s[j] != '\\':
            j += 1
        run = s[i:j]
        if len(run) >= 3:
            out.append('\\x%02d%s' % (len(run), s[i]))
        else:
            out.append(run)
        i = j
    return ''.join(out)

def rle_decode(s):
    out, i = [], 0
    while i < len(s):
        if s[i] == '\\':
            if s[i + 1] == '\\':
                out.append('\\')
                i += 2
            else:
                n = int(s[i + 2:i + 4])
                out.append(s[i + 4] * n)
                i += 5
        else:
            out.append(s[i])
            i += 1
    return ''.join(out)

from datetime import datetime

def max_errors_in_window(log_text, window_sec):
    fmt = '%Y-%m-%d %H:%M:%S'
    ts = []
    for line in log_text.strip().splitlines():
        parts = line.split(' ', 3)
        if len(parts) >= 3 and parts[2] == 'ERROR':
            ts.append(datetime.strptime(parts[0] + ' ' + parts[1], fmt).timestamp())
    ts.sort()
    best = 0
    j = 0
    for i, t in enumerate(ts):
        while ts[j] < t - window_sec:
            j += 1
        best = max(best, i - j + 1)
    return best

def semver_sort(versions):
    def key(v):
        core, _, pre = v.partition('-')
        nums = tuple(int(x) for x in core.split('.'))
        if not pre:
            return (nums, (1,))
        parts = []
        for ident in pre.split('.'):
            parts.append((0, int(ident)) if ident.isdigit() else (1, ident))
        return (nums, (0, parts))
    return sorted(versions, key=key)

import re

def camel_to_snake(s):
    s = re.sub(r'([A-Z]+)([A-Z][a-z])', r'\1_\2', s)
    s = re.sub(r'([a-z0-9])([A-Z])', r'\1_\2', s)
    return s.lower()

def min_remove_parens(s):
    chars = list(s)
    stack = []
    for i, ch in enumerate(chars):
        if ch == '(':
            stack.append(i)
        elif ch == ')':
            if stack:
                stack.pop()
            else:
                chars[i] = ''
    for i in stack:
        chars[i] = ''
    return ''.join(chars)

def shell_split(cmd):
    out, cur, quote = [], [], None
    for ch in cmd:
        if quote:
            if ch == quote:
                quote = None
            else:
                cur.append(ch)
        elif ch in '\'"':
            quote = ch
        elif ch == ' ':
            if cur:
                out.append(''.join(cur))
                cur = []
        else:
            cur.append(ch)
    if quote:
        raise ValueError('unmatched quote')
    if cur:
        out.append(''.join(cur))
    return out

from decimal import Decimal, ROUND_HALF_UP

def invoice_total(items):
    rates = {'food': 0, 'books': 5}
    total = Decimal('0')
    for name, cat, qty, price in items:
        rate = Decimal(rates.get(cat, 10)) / 100
        line = Decimal(str(qty)) * Decimal(str(price)) * (1 + rate)
        total += line.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    return float(total)

def parse_ini(text):
    out = {}
    section = ''
    out[section] = {}
    for line in text.splitlines():
        line = line.strip()
        if not line or line.startswith(';'):
            continue
        if line.startswith('[') and line.endswith(']'):
            section = line[1:-1].strip()
            out.setdefault(section, {})
        else:
            k, _, v = line.partition('=')
            out[section][k.strip()] = v.strip()
    return out

def word_search(grid, word):
    R, C = len(grid), len(grid[0])
    grid = [list(row) for row in grid]
    def dfs(r, c, i):
        if i == len(word):
            return True
        if r < 0 or c < 0 or r >= R or c >= C or grid[r][c] != word[i]:
            return False
        ch, grid[r][c] = grid[r][c], '#'
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            if dfs(r + dr, c + dc, i + 1):
                return True
        grid[r][c] = ch
        return False
    return any(dfs(r, c, 0) for r in range(R) for c in range(C))

def brace_expand(s):
    parts = []
    i = 0
    while i < len(s):
        if s[i] == '{':
            j = s.index('}', i)
            opts = s[i+1:j].split(',')
            if len(opts) == 1:
                parts.append(['{' + opts[0] + '}'])
            else:
                parts.append(opts)
            i = j + 1
        else:
            j = i
            while j < len(s) and s[j] != '{':
                j += 1
            parts.append([s[i:j]])
            i = j
    out = ['']
    for opts in parts:
        out = [p + o for p in out for o in opts]
    return out

def words_to_number(text):
    units = {'zero':0,'one':1,'two':2,'three':3,'four':4,'five':5,'six':6,
             'seven':7,'eight':8,'nine':9,'ten':10,'eleven':11,'twelve':12,
             'thirteen':13,'fourteen':14,'fifteen':15,'sixteen':16,
             'seventeen':17,'eighteen':18,'nineteen':19}
    tens = {'twenty':20,'thirty':30,'forty':40,'fifty':50,'sixty':60,
            'seventy':70,'eighty':80,'ninety':90}
    total, current = 0, 0
    for w in text.replace('-', ' ').split():
        if w in units:
            current += units[w]
        elif w in tens:
            current += tens[w]
        elif w == 'hundred':
            current *= 100
        elif w == 'thousand':
            total += current * 1000
            current = 0
        else:
            raise ValueError('unknown word: ' + w)
    return total + current

def parse_md_table(text):
    lines = [l for l in text.strip().splitlines() if l.strip()]
    def cells(line):
        line = line.strip()
        if line.startswith('|'):
            line = line[1:]
        if line.endswith('|'):
            line = line[:-1]
        return [c.strip() for c in line.split('|')]
    header = cells(lines[0])
    rows = []
    for line in lines[2:]:
        vals = cells(line)
        rows.append(dict(zip(header, vals)))
    return rows

def parse_csv_line(line):
    out, cur, i = [], [], 0
    in_q = False
    while i < len(line):
        c = line[i]
        if in_q:
            if c == '"':
                if i + 1 < len(line) and line[i + 1] == '"':
                    cur.append('"')
                    i += 2
                    continue
                in_q = False
            else:
                cur.append(c)
        else:
            if c == '"':
                in_q = True
            elif c == ',':
                out.append(''.join(cur))
                cur = []
            else:
                cur.append(c)
        i += 1
    out.append(''.join(cur))
    return out

def base32_decode(s):
    alpha = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567'
    s = s.upper().rstrip('=')
    bits = 0
    nbits = 0
    out = bytearray()
    for c in s:
        bits = (bits << 5) | alpha.index(c)
        nbits += 5
        if nbits >= 8:
            nbits -= 8
            out.append((bits >> nbits) & 0xFF)
    return bytes(out)

