class RingBuffer:
    def __init__(self, capacity):
        self.capacity = capacity
        self._buf = []

    def append(self, x):
        self._buf.append(x)
        if len(self._buf) > self.capacity:
            self._buf.pop(0)

    def items(self):
        return list(self._buf)

